def find_4comp(grid, color):
    visited = set()
    comps = []
    def dfs(r, c):
        stack = [(r, c)]
        comp = set()
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            comp.add((cr, cc))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] == color and (nr, nc) not in visited:
                        stack.append((nr, nc))
        return comp
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r, c) not in visited:
                comp = dfs(r, c)
                if comp:
                    comps.append(comp)
    return comps

def get_bbox_size(grid, comp):
    r_min, r_max = min(p[0] for p in comp), max(p[0] for p in comp)
    c_min, c_max = min(p[1] for p in comp), max(p[1] for p in comp)
    return (r_min, r_max, c_min, c_max)

def get_subgrid(grid, bbox):
    r_min, r_max, c_min, c_max = bbox
    return [grid[r][c_min:c_max+1] for r in range(r_min, r_max+1)]

def is_hollow_box(subgrid):
    h, w = len(subgrid), len(subgrid[0])
    if h < 3 or w < 3:
        return False
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h-1 or c == 0 or c == w-1):
                if subgrid[r][c] == 0:
                    return False
    for r in range(1, h-1):
        for c in range(1, w-1):
            if subgrid[r][c] != 0:
                return False
    return True

def is_filled_box(subgrid):
    h, w = len(subgrid), len(subgrid[0])
    if h < 2 or w < 2:
        return False
    for row in subgrid:
        if 0 in row:
            return False
    return True

def shape_to_info(subgrid):
    h, w = len(subgrid), len(subgrid[0])
    if is_hollow_box(subgrid):
        return "hollow_box"
    if is_filled_box(subgrid):
        return "filled"
    filled = sum(sum(row) for row in subgrid)
    total = h * w
    if filled == 1:
        return "singleton"
    if filled == w + h - 1:  # L-shape (two intersecting lines)
        return "L_shape"
    if filled == 5 and h == w == 3:  # Plus sign
