def transform(grid):
    """Main transformation"""
    rows, cols = len(grid), len(grid[0])
    output = [[0 for _ in range(cols)] for _ in range(rows)]
    visited = set()

    # Find and transform components
    for color in range(1, 9):
        from collections import deque
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color and (r, c) not in visited:
                    # BFS to get component
                    comp = []
                    queue = deque([(r, c)])
                    visited.add((r, c))
                    while queue:
                        cr, cc = queue.popleft()
                        comp.append((cr, cc))
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == color and (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    queue.append((nr, nc))

                    # Get bbox
                    r_min, r_max = min(p[0] for p in comp), max(p[0] for p in comp)
                    c_min, c_max = min(p[1] for p in comp), max(p[1] for p in comp)

                    # Extract subgrid
                    subgrid = [grid[r][c_min:c_max+1] for r in range(r_min, r_max+1)]

                    # Analyze and determine output
                    shape_class, output_color, out_subgrid = analyze_shape(subgrid, color)

                    # Place at bottom-right
                    h, w = len(out_subgrid), len(out_subgrid[0])
                    out_r = rows - h
                    out_c = cols - w

                    for sr in range(h):
                        for sc in range(w):
                            if out_subgrid[sr][sc] != 0:
                                output[out_r + sr][out_c + sc] = output_color

    return output

